-- DARKSIDE // INBOX — SUPABASE DATA-DRIVEN SKIN ENGINE
-- Backward-compatible: existing legacy columns remain readable; new JSON config is additive.
create table if not exists public.app_themes (
  theme_key text primary key,
  name text not null,
  description text default '',
  category text default 'Cyberpunk',
  background_color text,
  surface_color text,
  primary_color text,
  accent_color text,
  text_primary_color text,
  text_secondary_color text,
  font_body text,
  font_heading text,
  border_style text,
  button_style text,
  radius numeric default 16,
  glow numeric default 18,
  motion_enabled boolean default true,
  config jsonb not null default '{}'::jsonb,
  is_enabled boolean not null default true,
  sort_order integer not null default 0,
  updated_at timestamptz not null default now()
);
create table if not exists public.chat_frames (
  id bigint generated by default as identity primary key,
  theme_key text not null references public.app_themes(theme_key) on delete cascade,
  name text default '',
  config jsonb not null default '{}'::jsonb,
  is_enabled boolean not null default true,
  unique(theme_key)
);
create table if not exists public.sound_packs (
  id bigint generated by default as identity primary key,
  theme_key text not null references public.app_themes(theme_key) on delete cascade,
  name text default '',
  notification_url text,
  click_url text,
  switch_url text,
  config jsonb not null default '{}'::jsonb,
  is_enabled boolean not null default true,
  unique(theme_key)
);

-- If app_themes already exists, add only the additive fields.
alter table public.app_themes add column if not exists category text default 'Cyberpunk';
alter table public.app_themes add column if not exists config jsonb not null default '{}'::jsonb;
alter table public.app_themes add column if not exists updated_at timestamptz not null default now();

on conflict (theme_key) do update set name=excluded.name,description=excluded.description,category=excluded.category,background_color=excluded.background_color,surface_color=excluded.surface_color,primary_color=excluded.primary_color,accent_color=excluded.accent_color,text_primary_color=excluded.text_primary_color,text_secondary_color=excluded.text_secondary_color,font_body=excluded.font_body,font_heading=excluded.font_heading,border_style=excluded.border_style,button_style=excluded.button_style,radius=excluded.radius,glow=excluded.glow,motion_enabled=excluded.motion_enabled,config=excluded.config,is_enabled=excluded.is_enabled,sort_order=excluded.sort_order,updated_at=now();

on conflict (theme_key) do update set name=excluded.name,config=excluded.config,is_enabled=excluded.is_enabled;

on conflict (theme_key) do update set name=excluded.name,notification_url=excluded.notification_url,click_url=excluded.click_url,switch_url=excluded.switch_url,config=excluded.config,is_enabled=excluded.is_enabled;

-- Optional RLS: expose only enabled skins through your existing read policy.
-- create policy "public can read enabled skins" on public.app_themes for select using (is_enabled = true);
